const head=(t,backTarget='home',fieldId='')=>`<div class="page-head"><button class="back" ${fieldId?`data-field-id="${fieldId}"`:''} onclick="${backTarget==='work'?`workImport=false;renderAll()`:`go('${backTarget}')`}" aria-label="Back">${icon('i-back')}</button><h2 class="page-title">${t}</h2></div>`;
