function toggleNetworkDiagnosis(event,forceClose=false){event?.stopPropagation();const layer=document.getElementById('networkDiagnosis');if(!layer)return;layer.classList.toggle('open',forceClose?false:!layer.classList.contains('open'))}
// ── homeUI — 首页 UI
function homeUI(){return `<section class="tablet-screen home-screen" onclick="linkPRD('prdsec1')"><div class="home-left"><button class="home-icon" data-field-id="home-account" onclick="event.stopPropagation();go('account')" aria-label="Account"><img src="${IMG.account}"></button><button class="home-icon" data-field-id="home-general" onclick="event.stopPropagation();go('settings')" aria-label="General Settings"><img src="${IMG.leftSetting}"></button></div><div class="home-status"><button class="network-trigger clickable" data-field-id="home-network" onclick="toggleNetworkDiagnosis(event);highlightWorkField('home-network',this,true)" aria-label="Open Network Diagnostics"><span class="net">▫▫4G</span>${icon('i-wifi','wifi')}</button><img class="battery" data-field-id="home-battery" src="${GCS_BATTERY_IMG}" alt="Controller battery charging"><i class="sep"></i><span class="home-time" data-field-id="home-time" id="homeTime">05:30(GMT+08:00)</span><button class="home-gear" data-field-id="home-drone-settings" onclick="event.stopPropagation();go('droneSettings')" aria-label="Aircraft Settings">${icon('i-gear')}</button></div><div class="home-bottom"><button class="home-nav" data-field-id="home-work" onclick="event.stopPropagation();go('work')"><img src="${IMG.work}"><span class="home-nav-text">Mission Resources</span></button><button class="home-nav" data-field-id="home-logs" onclick="event.stopPropagation();go('logs')"><img src="${IMG.logs}"><span class="home-nav-text">Log Management</span></button><button class="home-nav" data-field-id="home-devices" onclick="event.stopPropagation();go('devices')"><img src="${IMG.devices}"><span><span class="home-nav-text">Device Management</span><span class="home-nav-tip">Update Available</span></span></button><button class="connect" data-field-id="home-connection" onclick="event.stopPropagation();highlightWorkField('home-connection',this,true)"><span class="connect-dot"><img src="${HOME_IMG.disconnect}" alt=""></span><span class="home-connect-label">Disconnected</span></button><button class="start-btn" data-field-id="home-start" onclick="event.stopPropagation();linkPRD('prdsec3')">Start</button></div><div class="network-diagnosis-layer" id="networkDiagnosis" onclick="toggleNetworkDiagnosis(event,true)"><div class="network-diagnosis-popup" role="dialog" aria-label="Network Diagnostics" onclick="event.stopPropagation()"><div class="network-diagnosis-title"><span>Network Diagnostics</span><span>›</span></div><div class="network-panel"><svg viewBox="0 0 318 216" aria-hidden="true"><g fill="none" stroke-linecap="round"><path d="M138 39H57V79" stroke="var(--theme)" stroke-width="3"/><path d="M180 39H261V79" stroke="#d7dde2" stroke-width="3"/><path d="M57 106V149H159" stroke="var(--theme)" stroke-width="3"/><path d="M261 106V149H159" stroke="#d7dde2" stroke-width="3"/><path d="M159 149V164" stroke="var(--theme)" stroke-width="3"/><rect x="22" y="164" width="274" height="45" rx="3" stroke="var(--theme)" stroke-width="1.8" stroke-dasharray="5 3"/></g></svg><img class="network-node rc" src="${HOME_IMG.diagGcs}"><img class="network-node wifi-node" src="${HOME_IMG.diagWifi}"><img class="network-node sim" src="${HOME_IMG.diagSimOff}"><img class="network-node video" src="${HOME_IMG.diagP2p}"><img class="network-node cloud" src="${HOME_IMG.diagWeb}"></div></div></div></section>`}
let droneLayerOrigin='home';
// ── homeWithDroneLayer — 首页叠加无人机小窗
function homeWithDroneLayer(layer){
  const background=droneLayerOrigin==='flightManual'&&SCREENS.flightManual
    ?SCREENS.flightManual.ui()
    :homeUI();
  return background.slice(0,-10)+layer+'</section>';
}
// ── droneLayer — 无人机连接小窗
function droneLayer(content){return homeWithDroneLayer(`<div class="drone-page" onclick="event.stopPropagation()"><div class="drone-panel">${content}</div></div><div class="system-toast" id="systemToast"></div>`)}


