let workTab='plot',workStore='local',workMulti=false,workSync=true,workOrder='desc',workImport=false;
// ── workAction — 作业资源操作
function workAction(id,action){const prd=document.querySelector('.prd-col'),top=prd?prd.scrollTop:0;action();renderAll();if(prd)prd.scrollTop=top;requestAnimationFrame(()=>highlightWorkField(id,document.querySelector(`[data-field-id="${id}"]`),false))}
// ── setWorkTab — 切换作业 Tab
function setWorkTab(tab,id){workAction(id,()=>{workTab=tab;workMulti=false})}
// ── setWorkStore — 切换本地/云端
function setWorkStore(store){workAction(`wstore-${store}`,()=>{workStore=store;workMulti=false})}
// ── toggleWorkSync — 切换云同步
function toggleWorkSync(){workAction('wsync',()=>workSync=!workSync)}
// ── toggleWorkMulti — 切换多选
function toggleWorkMulti(){workAction('wmulti',()=>workMulti=!workMulti)}
// ── toggleWorkOrder — 切换排序
function toggleWorkOrder(){workAction('wsort',()=>workOrder=workOrder==='desc'?'asc':'desc')}
// ── workImportUI — 二维码导入弹窗
function workImportUI(){return `<section class="tablet-screen page work-import-screen">${head('Import Field','work')}<div class="work-import-body"><div class="work-import-left"><svg class="work-qr" viewBox="0 0 120 120" aria-label="Field import QR code"><rect width="120" height="120" fill="#fff"/><g fill="#000"><path d="M8 8h34v34H8zm7 7v20h20V15zM78 8h34v34H78zm7 7v20h20V15zM8 78h34v34H8zm7 7v20h20V85z"/><path d="M51 8h9v9h-9zm12 0h8v17h-8zm-12 21h8v9h-8zm12 5h9v17h-9zm-12 13h9v9h-9zm27 4h9v9h-9zm13-4h8v17h-8zm13 2h8v8h-8zM48 64h9v9h-9zm13-4h9v18h-9zm14 4h8v9h-8zm13 5h9v8h-9zm13-4h11v9h-11zM48 82h9v9h-9zm13 3h8v9h-8zm14-5h9v18h-9zm13 4h8v9h-8zm13-3h11v9h-11zM48 102h18v10H48zm25 1h9v9h-9zm15-4h9v13h-9zm13 4h11v9h-11z"/></g></svg><p>Scan the QR code above or open this address in a browser<br>172.30.77.230:7777/</p><em>Keep the controller and the other device on the same network.</em></div><div class="work-import-divider"></div><div class="work-import-right"><div class="work-import-empty">No imported files</div><div class="work-import-footer"><span class="work-box"></span><span>All</span><button>Delete</button></div></div></div></section>`}
// ── workCloudCards — 云地块卡片
function workCloudCards(){if(workStore!=='cloud')return '';if(workTab!=='plot')return `<div class="work-cloud-empty clickable" data-field-id="wlist-${workTab}" onclick="highlightWorkField('wlist-${workTab}',this)">${workTab==='running'?'No active fields':'No prescription maps'}</div>`;return `<div class="work-card-list"><article class="work-card clickable" data-field-id="wcloud-card" onclick="highlightWorkField('wcloud-card',this)"><div class="work-card-map"><svg viewBox="0 0 100 100"><path d="M18 64L52 13 45 42 77 43 80 57 66 68 58 54 39 62 38 88 23 82z"/></svg></div><div class="work-card-info"><small>2026-08-13 17:23:45</small><strong>2026-08-13-17:11:06</strong><p>685 Xuxiang Road, Qingpu District, Shanghai, near the Dongfang Yiyun Health Industry Headquarters...</p></div><div class="work-card-meta"><strong>4.47 acres</strong><span>Polygon Field</span></div></article><article class="work-card clickable" data-field-id="wcloud-card" onclick="highlightWorkField('wcloud-card',this)"><div class="work-card-map"><svg viewBox="0 0 100 100"><path d="M13 32L78 12 79 80 22 87z"/></svg></div><div class="work-card-info"><small>2026-08-13 13:45:08</small><strong>2026-08-12-16:33:05</strong><p>685 Xuxiang Road, Qingpu District, Shanghai, near the Dongfang Yiyun Health Industry Headquarters...</p></div><div class="work-card-meta"><strong>1.31 acres</strong><span>Polygon Field</span></div></article></div>`}
// ── workUI — 作业资源主 UI
function workUI(){if(workImport)return workImportUI();const isPlot=workTab==='plot',isLocal=workStore==='local';return `<section class="tablet-screen page work-screen">${head('Mission Resources')}${isPlot?`<button class="head-action head-plus clickable" data-field-id="wimport" onclick="workAction('wimport',()=>workImport=true)" aria-label="Import Field">＋</button>`:''}<div class="page-body"><aside class="work-side"><button data-field-id="wtab-plot" class="clickable ${workTab==='plot'?'on':''}" onclick="setWorkTab('plot','wtab-plot')">Fields</button><button data-field-id="wtab-running" class="clickable ${workTab==='running'?'on':''}" onclick="setWorkTab('running','wtab-running')">In Progress</button><button data-field-id="wtab-tif" class="clickable ${workTab==='tif'?'on':''}" onclick="setWorkTab('tif','wtab-tif')">Prescription Maps</button></aside><div class="work-main"><div class="segmented"><button data-field-id="wstore-local" class="clickable ${isLocal?'on':''}" onclick="setWorkStore('local')">Local</button><button data-field-id="wstore-cloud" class="clickable ${!isLocal?'on':''}" onclick="setWorkStore('cloud')">Cloud</button></div>${!workMulti&&isLocal?`<button data-field-id="wsort" class="work-sort clickable ${workOrder}" onclick="toggleWorkOrder()">Time<span class="work-sort-arrows">◆</span></button>`:''}${!workMulti&&isPlot&&isLocal?`<button data-field-id="wsync" class="work-cloud clickable" onclick="toggleWorkSync()"><span class="fake-check ${workSync?'checked':''}">${workSync?'✓':''}</span>Auto-sync to Cloud</button>`:''}<div class="work-search ${workMulti?'multi':''}">${!workMulti?`<label class="clickable" data-field-id="wsearch" onclick="highlightWorkField('wsearch',this)"><span class="work-search-icon"></span><input aria-label="Search by name" placeholder="Enter a name" onclick="event.stopPropagation();highlightWorkField('wsearch',this.parentElement)"></label>`:''}<button data-field-id="wmulti" class="outline-sm clickable" onclick="toggleWorkMulti()">Select</button></div>${workCloudCards()}${workMulti?`<div class="work-multi-footer clickable" data-field-id="wbatch" onclick="highlightWorkField('wbatch',this)"><label><span class="work-box"></span>All</label>${isLocal?`<label><span class="work-box"></span>Not Synced</label>`:''}<span class="work-selected">Selected: 0</span><button class="work-delete">Delete</button><button class="work-transfer">${isLocal?'Upload':'Download'}</button></div>`:''}</div></div></section>`}


