/* ===========================================
 * 【🟡 03 日志管理】
 * ────────────────────────────────────────────
 * 当前日志 Tab（共 20 项）
 * ============================================ */

let logTab='controller',logPrompt='',logManager=false,logManagerTab='pending',logExpanded='',logSelectedGroups=new Set(),logTxSection='controller',logTxSelected=new Set(),logTxLoading=false,logCrash=false,logUploadDialog=false,logTxSwitch=false;
// ── logAction — 日志操作
function logAction(id,action,preserve=true){const prd=document.querySelector('.prd-col'),main=document.querySelector('.log-main'),pt=prd?prd.scrollTop:0,mt=main?main.scrollTop:0;action();renderAll();requestAnimationFrame(()=>{const p=document.querySelector('.prd-col'),m=document.querySelector('.log-main');if(p)p.scrollTop=pt;if(preserve&&m)m.scrollTop=mt;highlightWorkField(id,document.querySelector(`[data-field-id="${id}"]`),false)})}
// ── logDisconnectedMessage — 断连提示
function logDisconnectedMessage(tab){return tab==='drone'?'Connect the aircraft before uploading logs.':tab==='charger'?'Connect the charger before uploading logs.':'No logs found'}
// ── setLogTab — 切换日志 Tab
function setLogTab(tab){logAction(`log-tab-${tab}`,()=>{logTab=tab;logPrompt='';logUploadDialog=false;if(tab==='transmission'){logTxLoading=true;setTimeout(()=>{logTxLoading=false;renderAll()},720)}},false)}
// ── closeLogPrompt — 关闭日志提示
function closeLogPrompt(){logAction(`log-tab-${logTab}`,()=>logPrompt='')}
// ── toggleLogGroup — 展开日志分组
function toggleLogGroup(name){logAction('log-group-expand',()=>logExpanded=logExpanded===name?'':name)}
// ── toggleLogSelect — 切换日志选中
function toggleLogSelect(name){logAction('log-group-select',()=>logSelectedGroups.has(name)?logSelectedGroups.delete(name):logSelectedGroups.add(name))}
// ── toggleTxSelect — 切换已传日志选中
function toggleTxSelect(name){logAction('log-tx-file',()=>logTxSelected.has(name)?logTxSelected.delete(name):logTxSelected.add(name))}
// ── logCanUpload — 判断可上传
function logCanUpload(){return logTab==='controller'?logSelectedGroups.size>0:logTab==='transmission'?logTxSelected.size>0:false}
// ── logTxTotal — 已传日志总数
function logTxTotal(){let bytes=0;LOG_TX_FILES.forEach(f=>{if(!logTxSelected.has(f[0])||f[1]==='—')return;const n=parseFloat(f[1]);bytes+=f[1].endsWith('KB')?n*1024:f[1].endsWith('MB')?n*1024*1024:n});const size=bytes>=1048576?`${(bytes/1048576).toFixed(3)}MB`:bytes>=1024?`${(bytes/1024).toFixed(3)}KB`:`${bytes.toFixed(3)}B`;return `Selected: ${logTxSelected.size} video link logs${logTxSelected.size?`, Total: ${size}`:''}`}
// ── openLogRemark — 打开 30 字备注
function openLogRemark(){if(!logCanUpload())return;logAction('log-upload',()=>logUploadDialog=true)}
// ── logTabsUI — 日志 Tab UI
function logTabsUI(){return `<div class="logs-tabs">${LOG_TABS.map(([id,label])=>`<button class="${logTab===id?'on':''}" data-field-id="log-tab-${id}" onclick="setLogTab('${id}')">${label}</button>`).join('')}</div>`}
// ── logFooterUI — 日志底部操作
function logFooterUI(){
 if(logTab==='video')return `<div class="log-footer"><div class="log-footer-spacer"></div><label class="log-check-label tx-all" data-field-id="log-video-all" onclick="logAction('log-video-all',()=>{})"><span class="log-check"></span>Select All</label><button class="action delete disabled" data-field-id="log-delete" onclick="logAction('log-delete',()=>{})">Delete</button><button class="action disabled" data-field-id="log-upload">Upload</button></div>`;
 if(logTab==='charger')return `<div class="log-footer"><div class="log-footer-spacer"></div><button class="action delete disabled" data-field-id="log-delete" onclick="logAction('log-delete',()=>{})">Delete</button><button class="action disabled" data-field-id="log-upload">Upload</button></div>`;
 if(logTab==='transmission')return `<div class="log-footer"><span class="log-footer-text tx-total">${logTxTotal()}</span><label class="log-check-label tx-all" data-field-id="log-tx-all" onclick="logAction('log-tx-all',()=>{if(logTxSelected.size===LOG_TX_FILES.length)logTxSelected.clear();else LOG_TX_FILES.forEach(x=>logTxSelected.add(x[0]))})"><span class="log-check ${logTxSelected.size===LOG_TX_FILES.length?'on':''}">${logTxSelected.size===LOG_TX_FILES.length?'✓':''}</span>Select All</label><button class="action delete ${logTxSelected.size?'':'disabled'}" data-field-id="log-delete" onclick="logAction('log-delete',()=>logTxSelected.clear())">Delete</button><button class="action ${logCanUpload()?'':'disabled'}" data-field-id="log-upload" onclick="openLogRemark()">Upload</button></div>`;
 const selected=[...logSelectedGroups].map(n=>LOG_GROUPS.find(g=>g.name===n)).filter(Boolean),total=selected.reduce((n,g)=>n+(g.size.endsWith('MB')?parseFloat(g.size):parseFloat(g.size)/1024),0),crash=logTab==='drone'?`<label class="log-check-label" data-field-id="log-crash" onclick="logAction('log-crash',()=>logCrash=!logCrash)"><span class="log-check ${logCrash?'on':''}">${logCrash?'✓':''}</span>Crash Logs</label>`:'';
 return `<div class="log-footer"><span class="log-footer-text">${selected.length?`Selected: ${selected.length} controller log groups; total: ${total.toFixed(3)}MB`:''}</span><div class="log-footer-spacer"></div>${crash}<button class="action ${logCanUpload()?'':'disabled'}" data-field-id="log-upload" onclick="openLogRemark()">Upload</button></div>`
}
// ── logControllerUI — 日志控制面板
function logControllerUI(){return `<div class="logs-summary" data-field-id="log-summary">16 controller log groups<button class="refresh" data-field-id="log-refresh" onclick="logAction('log-refresh',()=>{},false)">↻</button></div><div class="log-main">${LOG_GROUPS.map(g=>{const open=logExpanded===g.name,checked=logSelectedGroups.has(g.name);return `<article class="log-group ${open?'expanded':''}" data-field-id="log-group"><div class="log-group-head"><button class="log-group-select" data-field-id="log-group-select" onclick="event.stopPropagation();toggleLogSelect('${g.name}')"><span class="log-check ${checked?'on':''}">${checked?'✓':''}</span></button><button class="log-group-copy" onclick="toggleLogGroup('${g.name}')"><div class="log-group-name">${g.name}</div><div class="log-group-meta"><span>${g.time}</span><span>Count: ${g.count}</span><span>Size: ${g.size}</span></div></button><button data-field-id="log-group-expand" onclick="toggleLogGroup('${g.name}')"><span class="log-chevron"></span></button></div>${open?`<div class="log-children" data-field-id="log-child">${(g.children||[]).map(c=>`<div class="log-child"><span>${c[0]}</span><b>${c[1]}</b></div>`).join('')||'<div class="log-child"><span>File details for this log group have been archived.</span></div>'}</div>`:''}</article>`}).join('')}</div>${logFooterUI()}`}
// ── logWarningUI — 日志警告面板
function logWarningUI(message){return `<div class="logs-summary"><button class="refresh" data-field-id="log-refresh" onclick="logAction('log-refresh',()=>{},false)">↻</button></div><div class="log-main"><div class="log-warning"><i>!</i><span>${message}</span></div></div>${logFooterUI()}`}
// ── logVideoUI — 视频日志面板
