// ── logTransmissionUI — 传输日志面板
function logTransmissionUI(){if(logTxSection==='drone')return `<div class="logs-summary" data-field-id="log-summary">Video link logs: 0 items</div><div class="log-main"><div class="log-tx-layout"><aside class="log-tx-side"><button data-field-id="log-tx-device" onclick="logAction('log-tx-device',()=>logTxSection='controller',false)">Controller</button><button class="on" data-field-id="log-tx-device">Aircraft</button></aside><div class="log-warning"><i>!</i><span>Aircraft Disconnected</span></div></div></div>${logFooterUI()}`;
 const tools=`<div class="log-tx-tools"><div class="log-link-state" data-field-id="log-tx-status"><span class="rc">▣</span><i class="ok"></i><span>—</span><i class="tri"></i><span>●</span></div><span>Logging</span><button class="log-switch ${logTxSwitch?'on':''}" data-field-id="log-tx-switch" onclick="logAction('log-tx-switch',()=>logTxSwitch=!logTxSwitch)"></button><button class="refresh" data-field-id="log-refresh" onclick="logAction('log-refresh',()=>{},false)">↻</button></div>`;
 return `<div class="logs-summary" data-field-id="log-summary"><span>Video link logs: 13 items</span>${tools}</div><div class="log-main"><div class="log-tx-layout"><aside class="log-tx-side"><button class="on" data-field-id="log-tx-device">Controller</button><button data-field-id="log-tx-device" onclick="logAction('log-tx-device',()=>logTxSection='drone',false)">Aircraft</button></aside><section class="log-tx-panel"><div class="log-tx-list">${LOG_TX_FILES.map(f=>`<button class="log-tx-row ${f[2]?'folder':''}" data-field-id="log-tx-file" onclick="toggleTxSelect('${f[0]}')"><span class="log-check ${logTxSelected.has(f[0])?'on':''}">${logTxSelected.has(f[0])?'✓':''}</span><span class="log-folder-arrow">${f[2]?'›':''}</span><i class="file-icon"></i><span>${f[0]}</span><b>${f[2]?'':f[1]}</b></button>`).join('')}</div></section></div></div>${logFooterUI()}`}
// ── logManagerUI — 日志管理员面板
function logManagerUI(){return `<section class="tablet-screen logs-screen"><div class="log-manager"><button class="back" aria-label="Back to Log Management" data-field-id="log-upload-manager" onclick="logAction('log-upload-manager',()=>logManager=false,false)">${icon('i-back')}</button><div class="log-manager-tabs"><button class="${logManagerTab==='pending'?'on':''}" data-field-id="log-manager-pending" onclick="logAction('log-manager-pending',()=>logManagerTab='pending',false)">Not Uploaded</button><button class="${logManagerTab==='history'?'on':''}" data-field-id="log-manager-history" onclick="logAction('log-manager-history',()=>logManagerTab='history',false)">Upload History</button></div><div class="log-manager-line"></div><main class="log-manager-body">${logManagerTab==='pending'?`<div class="log-manager-summary"><span>Each aircraft power cycle creates one record.</span><span>0 records</span></div>`:`<div class="log-manager-summary"><span>Each aircraft power cycle creates one record.</span><span>1 records</span></div><div class="log-manager-card" data-field-id="log-manager-record"><span>54400015/crash/ann_20260807_155206.log</span><span>43.802KB</span><span class="qr-mini"></span></div>`}</main></div></section>`}
// ── logUploadDialogUI — 上传弹窗
function logUploadDialogUI(){return !logUploadDialog?'':`<div class="modal-mask"><div class="modal log-upload-dialog"><h3>Upload Logs</h3><input data-field-id="log-remark" maxlength="30" placeholder="Add a note for this log upload"><div class="dialog-actions"><button onclick="logAction('log-remark',()=>logUploadDialog=false)">Cancel</button><button onclick="logAction('log-upload',()=>logUploadDialog=false)">Start Upload</button></div></div></div>`}
// ── logsUI — 日志主 UI
function logsUI(){if(logManager)return logManagerUI();let content=logTab==='controller'?logControllerUI():logTab==='video'?logVideoUI():logTab==='transmission'?logTransmissionUI():logWarningUI(logDisconnectedMessage(logTab));return `<section class="tablet-screen logs-screen"><div class="page-head">${back()}${logTabsUI()}<button class="upload-manage" data-field-id="log-upload-manager" onclick="logAction('log-upload-manager',()=>logManager=true,false)">Upload Manager</button></div><div class="logs-body">${content}</div>${logPrompt?`<div class="modal-mask"><div class="modal"><h3>Notice</h3><p>${logPrompt}</p><button onclick="closeLogPrompt()">Got It</button></div></div>`:''}${logTxLoading?`<div class="log-query-mask"><div class="log-query-box"><strong>Query Video Link Logs</strong><span>Connecting to FTP...</span><i class="log-spinner"></i></div></div>`:''}${logUploadDialogUI()}</section>`}


