 rc:{title:'Controller',rows:[['Model','HD401B'],['Current Stick Mode','Mode 2'],['Serial Number','54400015'],['Firmware Version','Lahaina for arm64'],['System Version','hd405_domestic_v2'],['MCUVersion','0.0.0.31','Update'],['Survey Device Version','N/A'],['Controller IP Address','172.30.77.230','Refresh'],['appVersion','V4.4.0.18']]},
