// ── deviceFieldId — 设备字段 ID
function deviceFieldId(view,i){return `device-${view}-${i}`}
// ── deviceSetSpec — 设备规格配置
function deviceSetSpec(view,rows=[]){let fields=[],rules=[];if(view==='main'){fields=[{id:'device-tip',cells:['Update Check Result','Read-only Status','Update Check Service','Updated when the check is complete','Your software is up to date.']},{id:'device-check',cells:['Check for Updates','Action Button','Device Version Service','Checks versions without installing updates','Check for Updates']},{id:'device-card',cells:['Device Card','Composite Field','Device Connection and Version Reports','Fixed four-column layout; repeated cards share one field','7  device types']},{id:'device-version',cells:['Software Version','String','Device Version Report','Shown when connected','4.4.0.18']},{id:'device-state',cells:['Connection Status','Enum','Live Communication','Connected/Disconnected','Connected']}];rules=[{id:'device-tip',text:'The latest update check result appears at the top of the page.'},{id:'device-check',text:'Check for Updates refreshes the result without installing firmware.'},{id:'device-card',text:'Open any device card to view its in-app details. All seven cards share the Device Card semantic field.'},{id:'device-version',text:'Controller and video link cards show their software versions at the top.'},{id:'device-state',text:'Connected devices use normal icons and green status text; disconnected devices are grayed out.'}]}else{fields=rows.map((r,i)=>({id:deviceFieldId(view,i),cells:[r[0]||'Unnamed Module','Read-only Information',`${DEVICE_DATA[view]?.title||view}Version Report`,'May be empty when disconnected',r[1]||'-']}));rules=rows.map((r,i)=>({id:deviceFieldId(view,i),text:`’${r[0]||'Unnamed Module'}’Shown in device order. Select a row to locate its field specification.`}));rows.forEach((r,i)=>{if(r[2])rules.push({id:`${deviceFieldId(view,i)}c0`,text:`Select ${r[2]}’Action: ${r[0]}’; This prototype provides feedback only and does not update or write to a real device.`})});if(view==='charger'||view==='battery'){fields=[{id:'device-search',cells:[view==='charger'?'Search for Nearby Chargers':'Search for Nearby Batteries','Action Button','Bluetooth Device Scan','Simulated; no real device access','Search']},{id:'device-refresh',cells:['Refresh Nearby Devices','Icon Button','Bluetooth Device Scan','Simulated; no real device access','Refresh']}];rules=[{id:'device-search',text:'Select the center search button for simulated feedback. The prototype does not scan Bluetooth devices.'},{id:'device-refresh',text:'Select Refresh at the top right to repeat the search feedback without resizing the details window.'}]}if(view==='check'){fields=[{id:'device-check-empty',cells:['Update Check Content','Empty State','Update Check Service','Empty when there are no devices to check','-']}];rules=[{id:'device-check-empty',text:'The current device update page is blank except for its fixed title and Back button.'}]}}SCREENS.devices.prd.controlSpec={fields,baseRules:[],rules}}
// ── deviceOpen — 打开设备详情
function deviceOpen(view){deviceView=view;deviceToast='';renderAll()}
// ── deviceBack — 设备详情返回
function deviceBack(){if(deviceView==='main')go('home');else deviceOpen('main')}
// ── deviceFeedback — 设备反馈操作
function deviceFeedback(text,id){deviceToast=text;renderAll();requestAnimationFrame(()=>{const el=document.querySelector(`[data-field-id="${id}"]`);if(el)selectControlField(id,el)});setTimeout(()=>{deviceToast='';if(cur==='devices')renderAll()},1300)}
// ── deviceHeader — 设备头部信息
function deviceHeader(title,refresh=false){return `<div class="device-detail-head"><button class="back" onclick="deviceBack()" aria-label="Back to Device Management">${icon('i-back')}</button><h2 class="device-detail-title">${title}</h2>${refresh?`<button class="device-detail-refresh" data-field-id="device-refresh" onclick="deviceFeedback('Nearby devices refreshed','device-refresh')" aria-label="Refresh">↻</button>`:''}</div>`}
// ── deviceRows — 设备行数据
function deviceRows(view,rows){return rows.map((r,i)=>{const id=deviceFieldId(view,i),action=r[2]?`<button class="device-row-action" data-field-id="${id}c0" onclick="event.stopPropagation();deviceFeedback('${r[2]==='Update'?'Firmware updates are simulated in this prototype.':'IP address refreshed'}','${id}c0')">${r[2]}</button>`:'';return `<div class="device-row ${view==='drone'?'device-drone-row':''}" data-field-id="${id}" onclick="highlightField('${id}',this,'prdsec2')"><span class="device-row-label">${r[0]||'&nbsp;'}</span><span class="device-row-value">${r[1]||''}</span>${action}</div>`}).join('')}
// ── deviceDetailUI — 设备详情页（29 行）
function deviceDetailUI(view){if(view==='charger'||view==='battery'){deviceSetSpec(view);const label=view==='charger'?'Smart Charger':'Battery',search=view==='charger'?'Search for Nearby Chargers':'Search for Nearby Batteries';return `<section class="tablet-screen devices-screen">${deviceHeader(label,true)}<div class="device-empty"><button class="device-search-btn" data-field-id="device-search" onclick="deviceFeedback('Searching for nearby devices…','device-search')">${search}</button></div>${deviceToast?`<div class="device-toast">${deviceToast}</div>`:''}</section>`}if(view==='check'){deviceSetSpec(view);return `<section class="tablet-screen devices-screen">${deviceHeader('Update Check')}<div class="device-version-empty" data-field-id="device-check-empty" onclick="highlightField('device-check-empty',this,'prdsec2')"></div></section>`}const data=DEVICE_DATA[view];deviceSetSpec(view,data.rows);return `<section class="tablet-screen devices-screen">${deviceHeader(data.title)}<div class="device-detail-scroll">${deviceRows(view,data.rows)}</div>${deviceToast?`<div class="device-toast">${deviceToast}</div>`:''}</section>`}
// ── deviceCard — 设备卡片
function deviceCard(id,name,state,version=''){return `<button class="device-card ${state==='Connected'?'active':''}" data-field-id="device-card" onclick="deviceOpen('${id}')">${version?`<span class="version-ribbon" data-field-id="device-version">Software Version: ${version}</span>`:''}<img class="device-icon" src="${DEVICE_ICONS[id]}" alt=""><span class="device-name">${name}</span><span class="device-state" data-field-id="device-state">${state}</span></button>`}
// ── devicesUI — 设备总览 UI
function devicesUI(){if(deviceView!=='main')return deviceDetailUI(deviceView);deviceSetSpec('main');return `<section class="tablet-screen devices-screen"><div class="devices-head"><button class="back" onclick="go('home')" aria-label="Back to Home">${icon('i-back')}</button><h2 class="devices-title">Device Management</h2><div class="device-head-right"><button class="device-check" data-field-id="device-check" onclick="deviceFeedback('Your software is up to date.','device-check')">Check for Updates</button></div></div><div class="device-body"><div class="device-tip" data-field-id="device-tip" onclick="highlightField('device-tip',this,'prdsec2')">Your software is up to date.</div><div class="device-grid">${deviceCard('rc','Controller','Connected','4.4.0.18')}${deviceCard('drone','Aircraft','Disconnected')}${deviceCard('charger','Charger','Disconnected')}${deviceCard('battery','Battery','Disconnected')}${deviceCard('check','Update Check','Disconnected')}${deviceCard('transmission','Video Link Module','Connected','CX6672-CD_V2.10.00_R84_20260607')}${deviceCard('remoteId','Remote ID','Disconnected')}</div></div>${deviceToast?`<div class="device-toast">${deviceToast}</div>`:''}</section>`}

