const isDebugTab=()=>!RELEASE_TAB_IDS.has(droneTab);
// ── droneTabs — 当前无人机 Tab
function droneTabs(){return `<nav class="drone-tabs" onscroll="droneTabsScrollTop=this.scrollTop">${DEBUG_TABS.filter(x=>window.isCustomerSettingTab(x[0])).map(x=>{const selected=droneTab===x[0],menuIcon=DEBUG_MENU_ICONS[x[1]]||RELEASE_MENU_STATE_ICONS[x[1]],iconSrc=menuIcon?menuIcon[selected?1:0]:DRONE_ICONS[x[1]];return `<button class="drone-tab ${menuIcon?'debug-menu-state ':''}${selected?'on':''}" onclick="setDroneTab('${x[0]}')"><img src="${iconSrc}" alt="">${x[2]}</button>`}).join('')}</nav>`}
// ── setDroneTab — 切换无人机 Tab
function setDroneTab(id){if(!window.isCustomerSettingTab(id))return;const tabs=document.querySelector('.drone-tabs');if(tabs)droneTabsScrollTop=tabs.scrollTop;droneTab=id;if(typeof cur!=='undefined'&&cur!=='droneSettings')cur='droneSettings';renderAll();const nextTabs=document.querySelector('.drone-tabs');if(nextTabs)nextTabs.scrollTop=droneTabsScrollTop;setTimeout(()=>linkPRD('prdsec1'),0)}

