// ── otherTrigger — 其他触发器
function otherTrigger(key,field){return `<button type="button" class="other-popup-trigger" data-other-key="${key}" onpointerdown="event.preventDefault()" onclick="openOtherPopup(event,'${key}',this)"><span>${otherValues[key]}</span><img class="drop-arrow" src="./assets/RELEASE_MENU_STATE_ICONS_other_sel_1.png" alt=""></button>`}
// ── otherSettingsUI — 其他设置 UI
function otherSettingsUI(previewKey=''){droneTab='other';const rows=[['Voice Announcements<br><small>Voice announcements are recommended.</small>',dSwitch(true)],['Speech Rate',dStep('1.0')],['Speech Engine<br><small>Restart the app after changing the speech engine configuration.</small>','<button class="chev" onclick="showSystemToast(\'Speech Engine opens Android system settings.\')">›</button>'],['Front Camera Overlay',otherTrigger('frontView','r3')],['Rear Camera Overlay',otherTrigger('rearView','r4')],['Front Video Stream Parameters',otherTrigger('frontVideo','r5')],['Rear Video Stream Parameters',otherTrigger('rearVideo','r6')],['Language',otherTrigger('language','r7')],['Chengxin Care<br><small>The first year of Huida Care is included with your aircraft.</small>','<button class="chev" onclick="go(\'droneInsurance\')">›</button>'],['Android System Location Services','<button class="real-outline-btn" onclick="showSystemToast(\'Location services open Android system settings.\')">Open</button>']];const previewOptions=OTHER_POPUP_OPTIONS[previewKey];const popup=previewOptions?otherPopupMarkup(previewKey,previewOptions,previewKey==='language'?360:previewKey==='rearVideo'?315:250):'';return droneLayer(`${droneTabs()}<main class="drone-content other-real-content"><header class="drone-head">Other Settings</header><button class="drone-close" onclick="go('home')">×</button><div class="other-real-body" onscroll="otherScrollTop=this.scrollTop">${rows.map((r,i)=>`<div class="drone-row other-real-row clickable" data-field-id="r${i}" onclick="selectDroneField(${i},'${i===2||i===9?'prdsec6':'prdsec2'}',this)"><div>${r[0]}</div><span class="right">${i<3||i>7?bindControlFields(r[1],i):r[1]}</span></div>`).join('')}</div><div class="other-real-footer"><button onclick="showSettingsDialog('Restart the controller? This action is simulated.')">Restart</button><i></i><button onclick="showSettingsDialog('Shut down the controller? This action is simulated.')">Shut Down</button></div></main>${popup}`)}
// ── otherInsuranceUI — 其他保险 UI
function otherInsuranceUI(){droneTab='other';ACTIVE_SUB_ROWS=[['Chengxin Care','N/A'],['Third-Party Liability Coverage','N/A'],['Renewal Inspection','Unavailable while disconnected']];return droneLayer(`${droneTabs()}<main class="drone-content other-insurance-content"><header class="drone-head">Chengxin Care</header><button class="advanced-real-back" aria-label="Back to Other Settings" onclick="go('droneSettings')">‹</button><button class="other-insurance-renew clickable" data-field-id="s2" onclick="highlightField('s2',this,'prdsec3');showSettingsDialog('Connect the aircraft before renewing coverage.')">Renewal Inspection</button><button class="drone-close" onclick="go('home')">×</button><div class="other-insurance-body"><div class="other-insurance-row clickable" data-field-id="s0" onclick="highlightField('s0',this,'prdsec2')"><span>Chengxin Care</span><span>N/A</span></div><div class="other-insurance-row clickable" data-field-id="s1" onclick="highlightField('s1',this,'prdsec2')"><span>Third-Party Liability Coverage</span><span>N/A</span></div></div></main>`)}
// ── otherPopupMarkup — 其他弹窗 HTML
function otherPopupMarkup(key,options,top){return `<div class="other-popup-mask" onclick="closeOtherPopup()"><div class="other-popup-list" style="top:${Math.min(top,360)}px" onclick="event.stopPropagation()">${options.map(v=>`<button onclick="chooseOtherValue('${key}',this.textContent)">${v}</button>`).join('')}</div></div>`}
// ── openOtherPopup — 打开其他弹窗
function openOtherPopup(ev,key,trigger){ev.preventDefault();ev.stopImmediatePropagation();const body=document.querySelector('.other-real-body');otherScrollTop=body?.scrollTop||otherScrollTop;document.querySelector('.other-popup-mask')?.remove();body?.classList.add('popup-locked');if(body)body.scrollTop=otherScrollTop;const tablet=document.querySelector('.tablet'),tabletRect=tablet.getBoundingClientRect(),triggerRect=trigger.getBoundingClientRect(),scale=tabletRect.width/960||1;const rawTop=(triggerRect.bottom-tabletRect.top)/scale+5,top=Math.max(8,Math.min(360,rawTop));const options=OTHER_POPUP_OPTIONS[key]||[];const mask=document.createElement('div');mask.className='other-popup-mask';mask.onclick=closeOtherPopup;mask.innerHTML=`<div class="other-popup-list" style="top:${top}px" onclick="event.stopPropagation()">${options.map(v=>`<button type="button" onclick="chooseOtherValue('${key}',this.textContent)">${v}</button>`).join('')}</div>`;tablet.appendChild(mask);requestAnimationFrame(()=>{if(body)body.scrollTop=otherScrollTop})}
// ── closeOtherPopup — 关闭其他弹窗
function closeOtherPopup(){document.querySelector('.other-popup-mask')?.remove();const body=document.querySelector('.other-real-body');body?.classList.remove('popup-locked');if(body)body.scrollTop=otherScrollTop}
// ── chooseOtherValue — 选择其他值
function chooseOtherValue(key,value){otherValues[key]=value;const trigger=document.querySelector(`[data-other-key="${key}"] span`);if(trigger)trigger.textContent=value;closeOtherPopup()}
// ── droneSettingsUI — 无人机设置主 UI
function droneSettingsUI(){if(droneTab==='other')return otherSettingsUI();const titles={air:'Aircraft Settings',radar:'Sensing Settings',remote:'Controller Settings',spray:'Spray Settings',battery:'Smart Battery Settings',rtk:'RTK Settings',video:'405 Video Link Settings',other:'Other Settings'};const debug=DEBUG_PAGE_DATA[droneTab];const title=debug?debug.title:titles[droneTab];const rows=debug?debug.rows:droneRows();return droneLayer(`${droneTabs()}<main class="drone-content ${debug?'debug-page':''}"><header class="drone-head">${title}</header><button class="drone-close" onclick="go('home')">×</button>${rows.map((r,i)=>`<div class="drone-row clickable" data-field-id="r${i}" onclick="selectDroneField(${i},'${r[2]||'prdsec2'}',this)"><div>${r[0]}</div><span class="right">${bindControlFields(r[1],i)}</span></div>`).join('')}</main>`)}
// ── selectDroneField — 选中无人机字段
function selectDroneField(i,section,row){highlightField(`r${i}`,row,'prdsec2')}
// ── selectControlField — 选中控件字段
function selectControlField(id,control){const fieldId=id.replace(/c\d+$/,'');highlightField(fieldId,control,'prdsec3',id)}
// ── highlightField — 高亮字段
function highlightField(id,target,section,ruleId=id){document.querySelectorAll('.prd-row-focus').forEach(x=>x.classList.remove('prd-row-focus'));linkPRD(section);const tr=document.querySelector(`.prd-table tbody tr[data-field-id="${id}"]`);if(tr)tr.classList.add('prd-row-focus');const rule=document.querySelector(`#prdsec3 [data-field-id="${ruleId}"]`);if(rule)rule.classList.add('prd-row-focus')}
// ── highlightWorkField — 高亮作业字段
function highlightWorkField(id,target,scroll=false){document.querySelectorAll('.ui-field-focus').forEach(x=>x.classList.remove('ui-field-focus'));if(target)target.classList.add('ui-field-focus');document.querySelectorAll('.prd-row-focus').forEach(x=>x.classList.remove('prd-row-focus'));const tr=document.querySelector(`.prd-table tbody tr[data-field-id="${id}"]`),rule=document.querySelector(`#prdsec3 [data-field-id="${id}"]`);if(tr)tr.classList.add('prd-row-focus');if(rule)rule.classList.add('prd-row-focus');if(scroll&&tr){const col=document.querySelector('.prd-col');col.scrollTo({top:Math.max(0,tr.offsetTop-col.offsetTop-90),behavior:'smooth'})}}

let ACTIVE_SUB_ROWS=null;
// ── droneSubUI — 无人机子设置页
function droneSubUI(title,target,rows){ACTIVE_SUB_ROWS=rows;return `<section class="tablet-screen page">${subHead(title,target)}<div class="drone-subbody">${rows.map((r,i)=>`<div class="drone-subrow clickable" data-field-id="s${i}" onclick="highlightField('s${i}',this,'${r[2]||'prdsec2'}')"><span>${r[0]}</span><span class="right">${bindControlFields(r[1]||'',i,'s')}</span></div>`).join('')}</div></section>`}
// ── rtkSubUI — RTK 子 UI
function rtkSubUI(title,rows){droneTab='rtk';ACTIVE_SUB_ROWS=rows;const body=rows.map((r,i)=>`<div class="advanced-real-row clickable" data-field-id="s${i}" onclick="highlightField('s${i}',this,'${r[2]||'prdsec2'}')"><span>${r[0]}</span><span class="right">${bindControlFields(r[1]||'',i,'s')}</span></div>`).join('');return droneLayer(`${droneTabs()}<main class="drone-content advanced-real-content rtk-sub-content" data-subpage-title="${title}"><header class="drone-head">RTK Settings</header><button class="advanced-real-back" onclick="go('droneSettings')">‹</button><button class="drone-close" onclick="go('home')">×</button><div class="advanced-real-list">${body}</div></main>`)}
// ── rtkRealShell — RTK 真实外壳
function rtkRealShell(kind,body){droneTab='rtk';return droneLayer(`${droneTabs()}<main class="drone-content advanced-real-content rtk-sub-content" data-subpage-title="${kind}"><header class="drone-head">RTK Settings</header><button class="advanced-real-back" onclick="go('droneSettings')">‹</button><button class="drone-close" onclick="go('home')">×</button><div class="rtk-real-body">${body}</div></main>`)}
// ── rtkDiagnosisUI — RTK 诊断 UI
function rtkDiagnosisUI(){ACTIVE_SUB_ROWS=[['Positioning Satellite Count','0'],['Aircraft Connection','Disconnected'],['Controller Connection','Disconnected'],['Network RTK Connection','Normal'],['The aircraft cannot receive satellite positioning signals.','Error'],['The controller is disconnected from the aircraft.','Error'],['The controller is connected to network RTK or a mobile base station.','Normal']];return rtkRealShell('RTK Diagnostics',`<div class="rtk-diagnose-flow"><div class="rtk-flow-node clickable" data-field-id="s0" onclick="highlightField('s0',this,'prdsec2')"><span class="rtk-flow-icon sat">⌁<b>0</b></span><span>Satellite Positioning<br>Satellites</span></div><i class="rtk-flow-line"></i><div class="rtk-flow-node clickable" data-field-id="s1" onclick="highlightField('s1',this,'prdsec2')"><span class="rtk-flow-icon asset"><img src="${DRONE_ICONS.aircraft}" alt=""></span><span>Aircraft</span></div><i class="rtk-flow-line"></i><div class="rtk-flow-node clickable" data-field-id="s2" onclick="highlightField('s2',this,'prdsec2')"><span class="rtk-flow-icon asset"><img src="${DRONE_ICONS.remote_control}" alt=""></span><span>Controller</span></div><i class="rtk-flow-line on"></i><div class="rtk-flow-node clickable" data-field-id="s3" onclick="highlightField('s3',this,'prdsec2')"><span class="rtk-flow-icon rtk">RTK</span><span>Network RTK</span></div></div><div class="rtk-diagnose-results"><h3>Diagnostic Result:</h3><p class="rtk-error clickable" data-field-id="s4" onclick="highlightField('s4',this,'prdsec2')">1.The aircraft cannot receive satellite positioning signals.</p><p class="rtk-error clickable" data-field-id="s5" onclick="highlightField('s5',this,'prdsec2')">2.The controller is disconnected from the aircraft.</p><p class="rtk-ok clickable" data-field-id="s6" onclick="highlightField('s6',this,'prdsec2')">3.The controller is connected to network RTK or a mobile base station.</p></div>`)}
// ── rtkSnrUI — RTK 信噪比 UI
function rtkSnrUI(){ACTIVE_SUB_ROWS=[['Logging','Off'],['Current Satellite Count','0'],['Average SNR','N/A'],['Signal Source','GNSS1 / GNSS2 / Survey Device'],['SNR Chart','Empty'],['SNR Color Legend','0 / 10 / 20 / 30 / 50']];return rtkRealShell('RTK Satellite SNR',`<div class="rtk-snr-toolbar"><label class="rtk-log clickable" data-field-id="s0" onclick="highlightField('s0',this,'prdsec2')">log <button class="setting-switch" onclick="event.stopPropagation();this.classList.toggle('on')"></button></label><div class="rtk-snr-summary clickable" data-field-id="s1" onclick="highlightField('s1',this,'prdsec2')">Satellite Count: 0<br>Average SNR: N/A</div><div class="rtk-snr-tabs clickable" data-field-id="s3" onclick="highlightField('s3',this,'prdsec2')"><button class="on" onclick="toggleSegment(this)">GNSS1</button><button onclick="toggleSegment(this)">GNSS2</button><button onclick="toggleSegment(this)">Survey Device</button></div><span class="rtk-help">?</span></div><div class="rtk-snr-chart clickable" data-field-id="s4" onclick="highlightField('s4',this,'prdsec2')"></div><div class="rtk-snr-legend clickable" data-field-id="s5" onclick="highlightField('s5',this,'prdsec2')"><span>snr</span><i class="bar"></i><div class="ticks"><b>00</b><b>10</b><b>20</b><b>30</b><b>50</b></div></div>`)}
// ── gcsSnrBars — GCS 信噪比条
function gcsSnrBars(){return [[11,26],[11,28],[9,31],[13,32]].map((x,i)=>`<div class="gcs-snr-bar ${i===2?'bad':''}"><span>${x[0]}</span><i style="height:${28+x[0]*2}px"></i><b>${x[1]}<br>G</b></div>`).join('')}
// ── gcsSatelliteUI — GCS 卫星 UI
function gcsSatelliteUI(){droneTab='gps';ACTIVE_SUB_ROWS=[['Current Satellite Count','8'],['Average SNR','11'],['Upper Satellite SNR Chart','4 satellites'],['Lower Satellite SNR Chart','4 satellites'],['SNR Color Legend','0 / 10 / 20 / 30 / 50']];return droneLayer(`${droneTabs()}<main class="drone-content advanced-real-content gcs-snr-content"><header class="drone-head">Positioning</header><button class="advanced-real-back" onclick="go('droneSettings')">‹</button><button class="drone-close" onclick="go('home')">×</button><div class="gcs-snr-body"><div class="gcs-snr-summary clickable" data-field-id="s0" onclick="highlightField('s0',this,'prdsec2')"><span>Satellite Count: 8<br>Average SNR: 11</span><i class="gcs-snr-help">?</i></div><div class="gcs-snr-chart clickable" data-field-id="s2" onclick="highlightField('s2',this,'prdsec2')">${gcsSnrBars()}</div><div class="gcs-snr-chart second clickable" data-field-id="s3" onclick="highlightField('s3',this,'prdsec2')">${gcsSnrBars()}</div><div class="gcs-snr-legend clickable" data-field-id="s4" onclick="highlightField('s4',this,'prdsec2')"><span>snr</span><i class="bar"></i><div class="ticks"><b>00</b><b>10</b><b>20</b><b>30</b><b>50</b></div></div></div></main>`)}
// ── rtkDotUI — RTK 圆点 UI
function rtkDotUI(){ACTIVE_SUB_ROWS=[['RTK Survey Accuracy','1.6 ft'],['Aircraft Survey Accuracy','6.6 ft (disabled)']];return rtkRealShell('Survey Accuracy',`<div class="rtk-dot-row clickable" data-field-id="s0" onclick="highlightField('s0',this,'prdsec2')"><span>RTK Survey Accuracy</span><span class="right">${dStep('1.6',' ft')}</span></div><div class="rtk-dot-row disabled clickable" data-field-id="s1" onclick="highlightField('s1',this,'prdsec2')"><span>Aircraft Survey Accuracy</span><span class="right">${dStep('6.6',' ft')}</span></div>`)}
// ── toggleSegment — 开关式分段器
function toggleSegment(btn){btn.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('on'));btn.classList.add('on')}
// ── showSystemToast — 系统 Toast 提示
function showSystemToast(text='This opens Android system settings, which are outside this prototype.'){const el=document.getElementById('systemToast');el.textContent=text;el.style.display='block';clearTimeout(window.systemToastTimer);window.systemToastTimer=setTimeout(()=>el.style.display='none',2000)}
// ── showSettingsDialog — 通用设置弹窗
function showSettingsDialog(text){document.getElementById('tablet').insertAdjacentHTML('beforeend',`<div class="settings-modal"><div class="settings-dialog"><p>${text}</p><div class="actions"><button onclick="this.closest('.settings-modal').remove()">Cancel</button><button onclick="this.closest('.settings-modal').remove()">OK</button></div></div></div>`)}

