function openOfflineMap(){const type=document.getElementById('mapType').value;if(type==='Mapbox')go('offlineMap');else showSettingsDialog('This feature requires Mapbox. Change Map Type to Mapbox first.')}
// ── settingsUI — 设置总览
function settingsUI(){return `<section class="tablet-screen page">${head('General Settings')}<div class="settings-body"><button class="setting-row clickable" onclick="go('unitSettings')">Units <span class="right chev">›</span></button><div class="setting-row">Language <span class="right"><select class="lang-select" aria-label="Language"><option>English (US)</option></select></span></div><button class="setting-row clickable" onclick="go('voiceSettings')">Voice Settings <span class="right chev">›</span></button><div class="setting-row">Android System Location Services <span class="right"><button class="open-btn" onclick="showSystemToast()">Open</button></span></div><div class="setting-row">Region <span class="right">CN</span></div><button class="setting-row clickable" onclick="go('policySettings')">Regulatory Compliance <span class="right chev">›</span></button><div class="setting-row">Map Type <span class="right"><select class="lang-select" id="mapType" aria-label="Map Type"><option>Tianditu</option><option>Mapbox</option></select></span></div><button class="setting-row clickable" onclick="openOfflineMap()">Offline Maps <span class="right chev">›</span></button><div class="setting-row">Cache Size <span class="right"><button class="cache-btn" onclick="showSettingsDialog('Clear the app cache?')">Clear</button><span class="cache-size">171.20KB</span></span></div><button class="setting-row clickable" onclick="go('systemSettings')">System Settings <span class="right chev">›</span></button><button class="setting-row clickable" onclick="go('storage')">Storage <span class="right chev">›</span></button></div><div class="system-toast" id="systemToast"></div></section>`}
// ── unitSettingsUI — 单位设置
function unitSettingsUI(){return `<section class="tablet-screen page">${subHead('Units','settings')}<div class="settings-body"><div class="setting-row">Unit System <span class="setting-segments"><button onclick="toggleSegment(this)">Metric</button><button class="on" onclick="toggleSegment(this)">Imperial</button></span></div><div class="setting-row">Speed Unit <span class="setting-segments"><button onclick="toggleSegment(this)"> ft/s</button><button class="on" onclick="toggleSegment(this)"> mph</button></span></div><div class="setting-row">Temperature Unit <span class="setting-segments"><button onclick="toggleSegment(this)">Celsius</button><button class="on" onclick="toggleSegment(this)">Fahrenheit</button></span></div></div></section>`}
// ── changeSpeech — 切换语音播报
function changeSpeech(delta){const out=document.getElementById('speechRate');out.value=Math.min(2,Math.max(.5,Number(out.value)+delta)).toFixed(1)}
// ── voiceSettingsUI — 语音设置
function voiceSettingsUI(){return `<section class="tablet-screen page">${subHead('Voice Settings','settings')}<div class="settings-body"><div class="setting-row">Voice Announcements <button class="right setting-switch on" aria-label="Voice Announcements" onclick="this.classList.toggle('on')"></button></div><div class="setting-row">Speech Rate <span class="right stepper"><button onclick="changeSpeech(-.1)">−</button><output id="speechRate" value="1.0">1.0</output><button onclick="changeSpeech(.1)">＋</button></span></div><button class="setting-row system-link" onclick="showSystemToast('Speech Engine opens Android system settings, which are outside this prototype.')">Speech Engine <span class="info-dot" onclick="event.stopPropagation();document.getElementById('voiceTip').hidden=!document.getElementById('voiceTip').hidden">i</span><span class="right chev">›</span></button></div><div class="tip-bubble" id="voiceTip" hidden>Restart the app after changing the speech engine configuration.</div><div class="system-toast" id="systemToast"></div></section>`}
// ── policySettingsUI — 隐私政策
function policySettingsUI(){return `<section class="tablet-screen page">${subHead('Regulatory Compliance','settings')}<div class="policy-body"><div class="policy-card"><div class="policy-row">Flight Data Reporting <button class="right setting-switch on" aria-label="Report Flight Data" onclick="this.classList.toggle('on')"></button></div><p class="setting-tip">When flying in mainland China, applicable Chinese flight and civil UAS data rules require live flight data reporting. Keep reporting enabled. Data is sent over the network to the CAAC UTMISS system or cached locally when the network is unavailable. Huida does not store this data or forward it to other services.</p></div><div class="policy-card"><button class="policy-row clickable" onclick="go('realNameSettings')">CAAC Real-Name Aircraft Registration <span class="right chev">›</span></button><p class="setting-tip">Under China’s Interim Regulations on Unmanned Aircraft Flight Management, civil UAS owners must complete real-name registration before using their aircraft.</p></div></div></section>`}
// ── realNameSettingsUI — 实名认证
function realNameSettingsUI(){return `<section class="tablet-screen page">${subHead('Aircraft Registration','policySettings')}<div class="realname-body"><div class="realname-layout"><div class="realname-text"><h3>Step 1: Download the UOM App</h3><p>Scan the QR code with your phone to download UOM, the civil UAS management platform.</p><h3>Step 2: Complete Registration</h3><p>1.Open UOM, create an account, and sign in.<br>2.Complete registration in the Real-Name Registration section.</p></div><div class="qr-faux" aria-label="UOM APPSample QR Code"></div></div></div></section>`}
// ── systemSettingsUI — 系统设置
function systemSettingsUI(){const rows=['Android System Settings','All Apps','System Brightness','System Volume','System Time Zone'];return `<section class="tablet-screen page">${subHead('System Settings','settings')}<div class="settings-body">${rows.map(x=>`<button class="setting-row system-link" onclick="showSystemToast('${x}Opens Android system settings, which are outside this prototype.')">${x}<span class="right chev">›</span></button>`).join('')}</div><div class="system-toast" id="systemToast"></div></section>`}
// ── offlineMapUI — 离线地图管理
function offlineMapUI(){return `<section class="tablet-screen offline-shell"><div class="offline-map-bg"></div><div class="offline-top"><button onclick="go('settings')">‹</button><strong>Offline Maps</strong></div><div class="offline-panel"><h3>Offline Map List</h3><div class="offline-empty">No offline maps</div><div class="offline-actions"><button onclick="showSettingsDialog('Enter an offline map name to start the simulated download.')">New</button><button onclick="showSettingsDialog('No offline map selected')">Delete</button></div></div><div class="offline-tools"><button>Map Planning ⌄</button><button onclick="showSettingsDialog('Move the map to select a download area.')">＋ Add Area</button></div><div class="offline-cross">＋</div></section>`}


