let flightVisualState='plot';
const FLIGHT_SHOTS={plot:'./flight-assets/start-after2.png',ab:'./flight-assets/start-ab.png',free:'./flight-assets/start-free.png',side:'./flight-assets/start-side-plot.png',layer:'./flight-assets/start-layer.png',plan:'./flight-assets/start-new.png'};
// ── flightFocus — 飞行焦点
function flightFocus(id,msg){highlightField(String(id),null,'prdsec3');if(msg){const t=document.getElementById('flightToast');if(t){t.textContent=msg;t.classList.add('show');clearTimeout(window.flightToastTimer);window.flightToastTimer=setTimeout(()=>t.classList.remove('show'),1500)}}}
// ── flightSet — 飞行设置
function flightSet(state,id,msg=''){flightVisualState=state;renderAll();requestAnimationFrame(()=>flightFocus(id,msg))}
// ── flightHot — 飞行热区
function flightHot(cls,label,handler){return `<button class="flight-hotspot ${cls}" aria-label="${label}" onclick="event.stopPropagation();${handler}"></button>`}
// ── flightManualUI — 开始作业主 UI
function flightManualUI(){const s=flightVisualState in FLIGHT_SHOTS?flightVisualState:'plot';const plan=s==='plan';let hits='';if(plan){hits+=flightHot('flight-hit-back','Back to Home',"go('home')");hits+=flightHot('flight-hit-gear','Aircraft Settings',"go('droneSettings')");hits+=flightHot('flight-hit-plan-tab-basic','Basic Parameters',"flightFocus(13,'Basic parameters displayed')");hits+=flightHot('flight-hit-plan-tab-point','Waypoint Parameters',"flightFocus(13,'Waypoint tab linked to its field specification')");hits+=flightHot('flight-hit-plan-tab-obstacle','Obstacle Parameters',"flightFocus(13,'Obstacle tab linked to its field specification')");hits+=flightHot('flight-hit-plan-inset','Uniform Inset',"flightFocus(14,'Uniform inset toggled')");hits+=flightHot('flight-hit-plan-minus1','Decrease Inset',"flightFocus(15,'Inset adjusted by one step')");hits+=flightHot('flight-hit-plan-plus1','Increase Inset',"flightFocus(15,'Inset adjusted by one step')");hits+=flightHot('flight-hit-plan-single','Single-Side Inset',"flightFocus(16,'Single-side inset toggled')");hits+=flightHot('flight-hit-plan-minus2','Decrease Route Spacing',"flightFocus(17,'Route spacing adjusted by one step')");hits+=flightHot('flight-hit-plan-plus2','Increase Route Spacing',"flightFocus(17,'Route spacing adjusted by one step')");hits+=flightHot('flight-hit-plan-minus3','Decrease Obstacle Margin',"flightFocus(18,'Obstacle margin adjusted by one step')");hits+=flightHot('flight-hit-plan-plus3','Increase Obstacle Margin',"flightFocus(18,'Obstacle margin adjusted by one step')");hits+=flightHot('flight-hit-plan-route','Obstacle Bypass Method',"flightFocus(19,'Switch between back-and-forth and bypass paths.')");hits+=flightHot('flight-hit-plan-mode','Map Planning Method',"flightFocus(20,'Select a map planning method.')");hits+=flightHot('flight-hit-plan-point-type','Boundary Point Type',"flightFocus(21,'Boundary point selected')");hits+=flightHot('flight-hit-plan-add','Add Boundary Point',"flightFocus(22,'Ready to add boundary points')");hits+=flightHot('flight-hit-plan-exit','Exit Planning',"flightSet('plot',23,'Map planning closed')");hits+=flightHot('flight-hit-plan-save','Save Plan',"flightFocus(24,'Demo mode does not write to real devices.')");}else{hits+=flightHot('flight-hit-back','Exit Mission',"go('home')");hits+=flightHot('flight-hit-gear','Aircraft Settings',"go('droneSettings')");hits+=flightHot('flight-hit-side','Expand Field List',"flightSet('side',7)");hits+=flightHot('flight-hit-side-close','Collapse Field List',"flightSet('plot',7)");hits+=flightHot('flight-hit-folder','Field List',"flightSet('side',7)");hits+=flightHot('flight-hit-eraser','Clear Track',"flightFocus(5,'No track to clear')");hits+=flightHot('flight-hit-home','Home Point',"flightFocus(5,'Aircraft disconnected. No home point available.')");hits+=flightHot('flight-hit-rc','Controller Location',"flightFocus(5,'Centered on the controller')");hits+=flightHot('flight-hit-locate','Center Map',"flightFocus(5,'Map centered on the current location')");hits+=flightHot('flight-hit-layer','Video Layout',"flightSet('layer',8)");hits+=flightHot('flight-hit-layer-close','Close Video Layout',"flightSet('plot',8)");hits+=flightHot('flight-hit-type-plot','Field Mission',"flightSet('plot',6)");hits+=flightHot('flight-hit-type-ab','AB Point Mission',"flightSet('ab',6)");hits+=flightHot('flight-hit-type-free','Free Route',"flightSet('free',6)");hits+=flightHot('flight-hit-new','New Mission',"flightSet('plan',11)");hits+=flightHot('flight-hit-edit','Edit Mission',"flightFocus(12,'No mission available to edit')");hits+=flightHot('flight-hit-call','Load Mission',"flightFocus(12,'No mission available to load')");hits+=flightHot('flight-hit-video','Video Preview',"flightFocus(9,'Aircraft disconnected. No video available.')");hits+=flightHot('flight-hit-hud','Flight HUD',"flightFocus(10,'Flight data updates with the device connection.')");if(s==='side'){hits+=flightHot('flight-hit-side-search','Search Fields',"flightFocus(7,'Enter a field name')");hits+=flightHot('flight-hit-side-sort','Sort Fields',"flightFocus(7,'Sort by distance or time.')");}}
return `<section class="tablet-screen flight-manual-screen flight-state-${s}" style="background-image:url('${FLIGHT_SHOTS[s]}')" onclick="flightFocus(0)">${hits}<div class="flight-toast" id="flightToast"></div></section>`}

