// ── hardwareShell — 硬件测试外壳
function hardwareShell(body,bodyClass='hardware-black'){droneTab='hardware';return droneLayer(`${droneTabs()}<main class="drone-content hardware-sub-content"><header class="drone-head">Hardware Tests</header><button class="advanced-real-back" onclick="go('droneSettings')">‹</button><button class="drone-close" onclick="go('home')">×</button><div class="hardware-sub-body ${bodyClass}">${body}</div></main>`)}
