function tpDebugUI(){return otherDebugShell(`<div class="tp-real"><span class="clickable" data-field-id="s0" onclick="highlightField('s0',this,'prdsec2')">${bindControlFields('<button>Read Configuration</button>',0,'s')}</span><div class="tp-line"></div></div>`,[['Read Configuration','Button']])}
// ── morningDebugUI — 晨间调试 UI
function morningDebugUI(){return otherDebugShell(`<div class="morning-real"><div class="morning-row actions clickable" data-field-id="s0" onclick="highlightField('s0',this,'prdsec2')"><span>Morningcore Logging</span>${bindControlFields('<button class="teal-pill">On</button><button class="teal-pill">Off</button>',0,'s')}</div>${[['Controller Power','27',1],['Main Controller Power','27',2]].map(x=>`<div class="morning-row clickable" data-field-id="s${x[2]}" onclick="highlightField('s${x[2]}',this,'prdsec2')"><span>${x[0]}</span><span class="right">${bindControlFields(dStep(x[1]),x[2],'s')}</span></div>`).join('')}<div class="morning-row clickable" data-field-id="s3" onclick="highlightField('s3',this,'prdsec2')"><span>[, ^DAPI: "CDB018D8", ]</span></div></div>`,[['Morningcore Logging','On/Off'],['Controller Power','27'],['Main Controller Power','27'],['Device Information','CDB018D8']])}
