function debugAuthUI(){const rows=[['Authentication Status','Debug ID in Use: No'],['Aircraft ID','<input placeholder="Enter aircraft ID">'],['Controller ID','<input placeholder="Enter controller ID">'],['Main Controller ID','<input placeholder="Enter main controller ID">'],['Reset','<button>Reset</button>'],['OK','<button>OK</button>']];return otherDebugShell(`<div class="debug-auth-real"><div class="debug-auth-status clickable" data-field-id="s0" onclick="highlightField('s0',this,'prdsec2')">Debug ID in Use: No</div>${[['Aircraft ID','Enter aircraft ID',1],['Controller ID','Enter controller ID',2],['Main Controller ID','Enter main controller ID',3]].map(x=>`<label class="debug-auth-row clickable" data-field-id="s${x[2]}" onclick="highlightField('s${x[2]}',this,'prdsec2')"><span>${x[0]}</span>${bindControlFields(`<input placeholder="${x[1]}">`,x[2],'s')}</label>`).join('')}<div class="debug-auth-actions">${bindControlFields('<button>Reset</button>',4,'s')}${bindControlFields('<button>OK</button>',5,'s')}</div></div>`,rows)}
