function otherRemoteIdUI(){const authSelect=debugSelect('Authentication Method',['No Authentication','US ASTM','EU ASD-STAN','Japan DIPS','CAAC China','Authentication Method']);const rows=[['Remote ID Toggle',dSwitch(true)],['Remote ID Authorization Time','N/A'],['Remote ID Authorization Type',authSelect],['Remote ID Authorization Code','<input maxlength="24" placeholder="Enter authorization code">'],['Authorize','<button>Authorize</button>']];return otherDebugShell(`<div class="remote-id-real"><div class="remote-id-row clickable" data-field-id="s0" onclick="highlightField('s0',this,'prdsec2')"><span>Remote ID Toggle</span><span class="right">${bindControlFields(dSwitch(true),0,'s')}</span></div><div class="remote-id-row clickable" data-field-id="s1" onclick="highlightField('s1',this,'prdsec2')"><span>Remote ID Authorization Time</span><span class="remote-id-time">N/A</span></div><div class="remote-id-row clickable" data-field-id="s2" onclick="highlightField('s2',this,'prdsec2')"><span>Remote ID Authorization Type</span><span class="right">${bindControlFields(authSelect,2,'s')}</span></div><label class="remote-id-row clickable" data-field-id="s3" onclick="highlightField('s3',this,'prdsec2')"><span>Remote ID Authorization Code</span>${bindControlFields('<input class="remote-id-code" maxlength="24" placeholder="Enter authorization code">',3,'s')}</label><div class="remote-id-action">${bindControlFields('<button>Authorize</button>',4,'s')}</div></div>`,rows)}
// ── radarRangeChart — 雷达距离图
function radarRangeChart(){const bars=Array.from({length:30},(_,i)=>{const x=27+i*20.25;return `<rect class="radar-bar" x="${x}" y="8" width="4" height="244" rx="2"/><text class="radar-index" x="${x+2}" y="276">${i+1}</text>`}).join('');return `<svg class="radar-range-svg" viewBox="0 0 650 675" preserveAspectRatio="none" aria-label="Live Radar Distance Chart"><g>${bars}</g><line class="radar-divider" x1="10" y1="291" x2="650" y2="291"/><g><text class="radar-axis" x="1" y="404">40</text><line class="radar-grid-line" x1="10" y1="400" x2="607" y2="400"/><text class="radar-axis" x="1" y="484">30</text><line class="radar-grid-line" x1="10" y1="480" x2="607" y2="480"/><text class="radar-axis" x="1" y="564">20</text><line class="radar-grid-line" x1="10" y1="560" x2="607" y2="560"/><text class="radar-axis" x="1" y="644">10</text><line class="radar-grid-line" x1="10" y1="640" x2="607" y2="640"/><text class="radar-axis" x="1" y="672">0</text></g></svg>`}
// ── radarMainBody — 雷达主体
function radarMainBody(){return `<div class="radar-main"><div class="radar-main-actions"><button onclick="go('frontRadarParams')">v2Front Radar Settings</button><button onclick="go('rotateRadarParams')">Rotating Radar Settings</button><button onclick="go('radarDistanceDetail')">Radar Display</button></div><div class="radar-main-row clickable" data-field-id="r3" onclick="selectDroneField(3,'prdsec2',this)"><span>On: front radar distance. Off: rear radar distance.</span>${dSwitch(true)}</div><div class="radar-main-row clickable" data-field-id="r4" onclick="selectDroneField(4,'prdsec2',this)"><span>Send Controller-Marked Static Obstacles to Flight Controller</span>${dSwitch(false)}</div><div class="radar-preview">${radarRangeChart()}</div></div>`}
// ── radarControl — 雷达控制
function radarControl(kind,value,options=[]){if(kind==='select')return debugSelect(value,options.length?options:[value]);if(kind==='switch')return dSwitch(value===true);if(kind==='text')return `<span class="radar-id-value">${value}</span>`;return dStep(String(value),options||'')}
// ── radarParamRows — 雷达参数行
function radarParamRows(rows){return rows.map((r,i)=>`<div class="radar-param-row ${r[1]==='text'?'radar-id-row':''} clickable" data-field-id="s${i}" onclick="highlightField('s${i}',this,'prdsec2')"><span>${r[0]}</span><span class="right">${radarControl(r[1],r[2],r[3])}</span></div>`).join('')}
// ── radarParamUI — 雷达参数 UI
function radarParamUI(rows){ACTIVE_SUB_ROWS=rows.map(r=>[r[0],String(r[2])]);return radarShell(`<div class="radar-param-list">${radarParamRows(rows)}</div>`)}
