// ── debugOtherPageBody — 其他调试主体
function debugOtherPageBody(){
 const status=['Roll','Pitch','Attitude Source','Speed Source','Position Source','imuGyroscope Source','imuAccelerometer Source','Barometer Source','Magnetometer Source','can0_stute','Front Left Atomizer','Front Right Atomizer','Rear Left Atomizer','Rear Right Atomizer','Spreader Module','Spray Tank','Airframe','Stator ESC','Obstacle Radar','Main Controller CPU Usage','Altitude Radar','Flight Controller Temperature','Altitude Radar'];
 let fieldIndex=0;
 const field=(cls,build,action='')=>{const i=fieldIndex++;return `<div class="${cls} clickable" data-field-id="r${i}" onclick="selectDroneField(${i},'prdsec2',this);${action}">${build(i)}</div>`};
 const topFlight=field('other-debug-select-row',i=>`<span>Flight Mode: Auto</span>${bindControlFields(debugSelect('Auto',['Auto','Manual']),i)}`);
 const topBarometer=field('other-debug-select-row',i=>`<span>Barometer Debug</span>${bindControlFields(debugSelect('Default',['Default','Barometer 1','Barometer 2']),i)}`);
 const unlock=field('other-debug-unlock-head',i=>`<span>Force Arm</span>${bindControlFields(dSwitch(false),i)}`);
 const statusHtml=status.map(x=>field('other-debug-status',()=>`<span>${x}:</span><b>---</b>`)).join('');
 const mqtt=field('other-debug-nav no-arrow',()=>`MQTTAircraft Point Spacing`);
 const swirl=field('other-debug-nav',()=>`Rotary Atomizer`,`go('swirlDebug')`);
 const fc=field('other-debug-nav',()=>`Flight Controller Parameter Debug`,`go('fcParams')`);
 const brand=field('other-debug-brand',i=>`<span>Brand Name</span>${bindControlFields(debugSelect('Huida',['Huida']),i)}`);
 const auth=field('other-debug-nav',()=>`Authenticate`,`go('debugAuth')`);
 const camera=field('other-debug-switch-row',i=>`<span>Camera Debug</span>${bindControlFields(dSwitch(false),i)}`);
 const board=field('other-debug-action-row',i=>`<span>Initialize BYNAV Board</span>${bindControlFields('<button>Initialize</button>',i)}`);
 const subPages=[['Controller Debug','rcParams'],['Other Debug Settings','otherParams'],['Controller MCU','mcuControl'],['TP','tpControl'],['Morningcore Debug','morningControl']].map(x=>field('other-debug-nav',()=>x[0],`go('${x[1]}')`)).join('');
 const workOpen=field('other-debug-nav no-arrow',()=>`Spray Start Lead Time Outside Mission Area`);
 const workClose=field('other-debug-nav no-arrow',()=>`Spray Stop Lead Time Outside Mission Area`);
 const rtk=field('other-debug-select-wide',i=>`<span>RTK Type</span>${bindControlFields(debugSelect('5-16',['5-16']),i)}`);
 const logs=['Radar Logging','Airframe Logging','LiDAR Logging','Raw LiDAR Logging','Save All Radar IMU Data','GPSLogging'].map(x=>field('other-debug-log-row',i=>`<span>${x}</span>${bindControlFields(dSwitch(false),i)}`)).join('');
 const appHome=field('other-debug-select-wide',i=>`<span>AppHome Image</span>${bindControlFields(debugSelect('Aircraft',['Aircraft']),i)}`);
 const install=field('other-debug-pill-row',i=>`<span></span>${bindControlFields('<button>Install Sogou Keyboard</button>',i)}`);
 const clear=field('other-debug-pill-row',i=>`<span>Emergency Disarm Notice Dismissal Time</span>${bindControlFields('<button>Clear</button>',i)}`);
 const capture=field('other-debug-capture',i=>`<span>MeiG 4G Module Log Capture</span>${bindControlFields('<button>Start Capture</button><button>Stop Capture</button>',i)}`);
 return `<div class="debug-real-body light other-debug-real">${topFlight}${topBarometer}<section class="other-debug-unlock">${unlock}<div class="other-debug-status-grid">${statusHtml}</div></section>${mqtt}${swirl}${fc}${brand}${auth}${camera}${board}${subPages}${workOpen}${workClose}${rtk}${logs}${appHome}${install}${clear}${capture}</div>`
}
