function flightManualUIV2(){if(!String(flightVisualState).startsWith('plan'))return flightManualUI();const s=FLIGHT_SHOTS[flightVisualState]?flightVisualState:'plan';let hits='';hits+=flightHot('flight-hit-back','Back to Home',"go('home')");hits+=flightHot('flight-hit-gear','Aircraft Settings',"go('droneSettings')");hits+=flightHot('flight-hit-plan-tab-basic','Basic Parameters',"flightSet('plan',13)");hits+=flightHot('flight-hit-plan-tab-point','Waypoint Parameters',"flightSet('planWaypoint',13)");hits+=flightHot('flight-hit-plan-tab-obstacle','Obstacle Parameters',"flightSet('planObstacle',13)");hits+=flightHot('flight-hit-plan-mode','Map Planning Method',"flightFocus(20,'Select a map planning method.')");hits+=flightHot('flight-hit-plan-point-type','Boundary Point Type',"flightFocus(21,'Boundary point selected')");hits+=flightHot('flight-hit-plan-add','Add Boundary Point',"flightFocus(22,'Ready to add boundary points')");hits+=flightHot('flight-hit-plan-exit','Exit Planning',"flightSet('plot',23,'Map planning closed')");hits+=flightHot('flight-hit-plan-save','Save Plan',"flightFocus(24,'Demo mode does not write to real devices.')");if(s==='plan'){hits+=flightHot('flight-hit-plan-inset','Uniform Inset',"flightFocus(14,'Uniform inset toggled')");hits+=flightHot('flight-hit-plan-minus1','Decrease Inset',"flightFocus(15,'Inset adjusted by one step')");hits+=flightHot('flight-hit-plan-plus1','Increase Inset',"flightFocus(15,'Inset adjusted by one step')");hits+=flightHot('flight-hit-plan-single','Single-Side Inset',"flightFocus(16,'Single-side inset toggled')");hits+=flightHot('flight-hit-plan-minus2','Decrease Route Spacing',"flightFocus(17,'Route spacing adjusted by one step')");hits+=flightHot('flight-hit-plan-plus2','Increase Route Spacing',"flightFocus(17,'Route spacing adjusted by one step')");hits+=flightHot('flight-hit-plan-minus3','Decrease Obstacle Margin',"flightFocus(18,'Obstacle margin adjusted by one step')");hits+=flightHot('flight-hit-plan-plus3','Increase Obstacle Margin',"flightFocus(18,'Obstacle margin adjusted by one step')");hits+=flightHot('flight-hit-plan-route','Obstacle Bypass Method',"flightFocus(19,'Switch between back-and-forth and bypass paths.')");hits+=flightHot('flight-hit-plan-scroll','Scroll Parameters Down',"flightSet('planMore',25)");}else if(s==='planMore'){hits+=flightHot('flight-hit-plan-scroll','Scroll Parameters Up',"flightSet('plan',15)");hits+=flightHot('flight-hit-plan-route','Obstacle Bypass Method',"flightFocus(19,'Switch between back-and-forth and bypass paths.')");hits+=flightHot('flight-hit-plan-scan','Edge Pass Type',"flightFocus(25,'Switch among No Edge Pass, Edge Pass, and Edge Only.')");hits+=flightHot('flight-hit-plan-segment','Route Split Settings',"flightFocus(26,'Open route split settings.')");hits+=flightHot('flight-hit-plan-offset','Route Offset Settings',"flightFocus(27,'Open route offset settings.')");hits+=flightHot('flight-hit-plan-start','Start Point Settings',"flightFocus(28,'Set the start point on the map.')");hits+=flightHot('flight-hit-plan-heading','Heading Settings',"flightFocus(29,'Set the heading on the map.')");}else if(s==='planWaypoint'){hits+=flightHot('flight-hit-waypoint-stick','Waypoint Offset Control',"flightFocus(30,'Fine-tune the current waypoint by direction.')");hits+=flightHot('flight-hit-waypoint-delete','Delete Waypoint',"flightFocus(33,'No waypoint available to delete')");hits+=flightHot('flight-hit-waypoint-prev','Previous Waypoint',"flightFocus(31,'Select the previous waypoint.')");hits+=flightHot('flight-hit-waypoint-next','Next Waypoint',"flightFocus(31,'Select the next waypoint.')");hits+=flightHot('flight-hit-waypoint-before','Insert Waypoint Before',"flightFocus(32,'Insert a waypoint before the current point.')");hits+=flightHot('flight-hit-waypoint-after','Insert Waypoint After',"flightFocus(32,'Insert a waypoint after the current point.')");}else{hits+=flightHot('flight-hit-obstacle-help','Obstacle Selection Instructions',"flightFocus(34,'Select an obstacle on the map first.')");}return `<section class="tablet-screen flight-manual-screen flight-state-${s}" style="background-image:url('${FLIGHT_SHOTS[s]}')" onwheel="flightPlanWheel(event)" onclick="flightFocus(0)">${hits}<div class="flight-toast" id="flightToast"></div></section>`}

